type Schedule = (run: () => void) => void;
function createBatcher<T>(flush: (items: T[]) => void, schedule: Schedule) {
  let queue: T[] = [];
  let scheduled = false;
  return {
    push(item: T): void {
      queue.push(item);
      if (scheduled) return;
      scheduled = true;
      schedule(() => {
        scheduled = false;
        const batch = queue;
        queue = [];
        flush(batch);
      });
    },
  };
}

